"""Find Eventual Safe States — three-colour DFS cycle detection.

A node is safe when every path out of it ends in a terminal node; colouring
grey while in the current stack detects the cycles that make a node unsafe.

Time: O(V + E)   Space: O(V)
"""
from typing import List


class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        WHITE, GREY, BLACK = 0, 1, 2
        colour = [WHITE] * len(graph)

        def safe(node: int) -> bool:
            if colour[node] != WHITE:
                return colour[node] == BLACK
            colour[node] = GREY
            for nxt in graph[node]:
                if not safe(nxt):
                    return False
            colour[node] = BLACK
            return True

        return [node for node in range(len(graph)) if safe(node)]
